#!/usr/bin/env bash
# AUTO-GENERATED by quick-build-wp (tools/quick-build-wp). Do not edit by hand.
# 用法: sudo bash install.sh [--dry-run]
set -euo pipefail

# ---- 可配置变量（全部带默认值，可用环境变量覆盖）----
DOMAIN="${DOMAIN:-blog.laal.top}"
PHP_VERSION="${PHP_VERSION:-8.1}"
WP_VERSION="${WP_VERSION:-latest}"
DB_NAME="${DB_NAME:-wp_$(printf '%s' "${DOMAIN}" | tr '.' '_')}"
DB_USER="${DB_USER:-wp_user}"
DB_PASS="${DB_PASS:-ChangeMe_default_only_for_dry_run}"
WEB_ROOT="${WEB_ROOT:-/var/www/${DOMAIN}}"
INSTALL_SSL="${INSTALL_SSL:-1}"
SSL_CERT="${SSL_CERT:-}"
SSL_KEY="${SSL_KEY:-}"

# ---- 解析脚本自身参数 ----
DRY_RUN=0
for arg in "$@"; do
  case "${arg}" in
    --dry-run) DRY_RUN=1 ;;
    *) echo "unknown argument: ${arg}" >&2; exit 2 ;;
  esac
done

# 命令执行封装：dry-run 只打印不写盘；真实执行原样调用。
_run() {
  if [ "${DRY_RUN}" -eq 1 ]; then
    echo "[dry-run] $*"
  else
    "$@"
  fi
}

info() { echo "[*] $*"; }

# 写文件封装：dry-run 只打印目标路径；真实执行先建目录再用 heredoc 落盘。
_write_conf() {
  target="$1"
  if [ "${DRY_RUN}" -eq 1 ]; then
    echo "[dry-run] write ${target}"
  else
    mkdir -p "$(dirname "${target}")"
    cat > "${target}"
  fi
}

# env-check — 1/8 环境自检
info "1/8 环境自检"
_run command -v curl
_run command -v tar

# install-nginx — 2/8 同机共存：确认既有 Nginx 在位，不重复安装
info "2/8 确认既有 Nginx（同机共存，不安装）"
if ! command -v nginx >/dev/null 2>&1; then
  echo "[fatal] 未检测到 nginx：共存模式要求复用既有 Nginx，请先在主机安装并启动" >&2
  exit 1
fi

# install-mysql — 3/8 安装 MySQL（已存在则跳过）
info "3/8 安装 MySQL"
if command -v mysqld >/dev/null 2>&1 || dpkg -l mysql-server >/dev/null 2>&1; then
  info "mysql-server 已存在，跳过"
else
  _run apt-get install -y mysql-server
  _run systemctl enable mysql
  _run systemctl start mysql
fi

# install-php — 4/8 安装 PHP（已存在对应 fpm 包则跳过）
info "4/8 安装 PHP ${PHP_VERSION}"
if dpkg -l "php${PHP_VERSION}-fpm" >/dev/null 2>&1; then
  info "php${PHP_VERSION}-fpm 已存在，跳过"
else
  _run apt-get install -y "php${PHP_VERSION}-fpm" "php${PHP_VERSION}-mysql" "php${PHP_VERSION}-cli"
  _run systemctl enable "php${PHP_VERSION}-fpm"
fi

# create-db — 5/8 创建数据库与专用账号
info "5/8 创建数据库与专用账号"
_run mysql -e "CREATE DATABASE IF NOT EXISTS \`${DB_NAME}\` CHARACTER SET utf8mb4;"
_run mysql -e "CREATE USER IF NOT EXISTS '${DB_USER}'@'localhost' IDENTIFIED BY '${DB_PASS}';"
_run mysql -e "GRANT ALL PRIVILEGES ON \`${DB_NAME}\`.* TO '${DB_USER}'@'localhost';"
_run mysql -e "FLUSH PRIVILEGES;"

# download-wp — 6/8 下载并解压 WordPress（站点目录已有 wp-load.php 则跳过）
info "6/8 下载 WordPress"
if [ -f "${WEB_ROOT}/wp-load.php" ]; then
  info "WordPress 已存在，跳过"
else
  _run mkdir -p "${WEB_ROOT}"
  _run curl -fSL "https://wordpress.org/wordpress-${WP_VERSION}.tar.gz" -o /tmp/wordpress.tar.gz
  _run tar -xzf /tmp/wordpress.tar.gz -C "${WEB_ROOT}" --strip-components=1
  _run chown -R www-data:www-data "${WEB_ROOT}"
fi

# nginx-site — 7/8 写入站点 Nginx 配置与伪静态规则
info "7/8 站点配置与伪静态"
_write_conf "/etc/nginx/sites-available/${DOMAIN}.conf" <<NGINX_EOF
server {
    listen 80;
    listen [::]:80;
    server_name ${DOMAIN};
    return 301 https://$host$request_uri;
}

server {
    listen 443 ssl;
    listen [::]:443 ssl;
    server_name ${DOMAIN};
    root ${WEB_ROOT};
    index index.php index.html;
    charset utf-8;

    # 复用主机既有 *.laal.top 泛域名证书：SSL_CERT / SSL_KEY 传 pem / key 路径；
    # 留空时由步骤 8 certbot --nginx 接管 TLS。本块不抢占默认站点。
    ssl_certificate ${SSL_CERT};
    ssl_certificate_key ${SSL_KEY};

    location / {
        try_files \$uri \$uri/ /index.php?\$args;
    }

    location ~ \.php$ {
        include snippets/fastcgi-php.conf;
        fastcgi_pass unix:/run/php/php${PHP_VERSION}-fpm.sock;
    }

    location ~* \.(env|git|htaccess)$ { deny all; }
}
NGINX_EOF
_run ln -sf "/etc/nginx/sites-available/${DOMAIN}.conf" "/etc/nginx/sites-enabled/${DOMAIN}.conf"
if [ -n "${SSL_CERT}" ] && [ -n "${SSL_KEY}" ]; then
  _run nginx -t
  _run systemctl reload nginx
else
  info "SSL_CERT/SSL_KEY 留空：跳过 nginx -t；证书待补齐或由步骤 8 certbot 接管"
fi

# ssl — 8/8 可选：申请并配置 HTTPS 证书
if [ "${INSTALL_SSL}" -eq 1 ]; then
  if [ -n "${SSL_CERT}" ] && [ -n "${SSL_KEY}" ]; then
    info "8/8 复用既有泛域名证书，跳过 certbot"
  else
    info "8/8 配置 HTTPS（certbot 接管 TLS）"
    if command -v certbot >/dev/null 2>&1; then
      _run certbot --nginx -d "${DOMAIN}" --non-interactive --agree-tos --register-unsafely-without-email
    else
      _run apt-get install -y certbot python3-certbot-nginx
      _run certbot --nginx -d "${DOMAIN}" --non-interactive --agree-tos --register-unsafely-without-email
    fi
  fi
else
  info "8/8 跳过 HTTPS（INSTALL_SSL=0）"
fi

info "完成：站点目录 ${WEB_ROOT}"
